'use strict';
window.BundleRemediation=class {
  constructor({host,api,url,current,storageKey,legacyAttachments,addEvidence,changed,dirty,download}){
    Object.assign(this,{host,api,url,current,storageKey,legacyAttachments,addEvidence,changed,dirty,download});
    this.pending=null;this.busy=false;this.drafts={};this.edited=new Set();this.localDirty=false;
    try{this.pending=JSON.parse(sessionStorage.getItem(storageKey));}catch{/* optional recovery */}
    if(this.pending)this.dirty(true);
  }
  node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
  field(label,tag='textarea',key){const wrap=this.node('label',label),input=this.node(tag);if(tag==='textarea'){input.rows=3;input.maxLength=4000;}wrap.append(input);if(key){input.dataset.draftKey=key;input.addEventListener('input',()=>{this.edited.add(key);this.localDirty=true;this.dirty(true);});}return {wrap,input};}
  options(input,values,selected){input.replaceChildren(...values.map(([value,text])=>{const o=this.node('option',text);o.value=value;return o;}));if(selected!==undefined)input.value=selected;}
  date(value){return value?new Date(value).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'Chưa đặt';}
  local(value){return value?new Date(Date.parse(value)+7*3600*1000).toISOString().slice(0,19):'';}
  saveDrafts(){for(const input of this.host.querySelectorAll('[data-draft-key]'))if(this.edited.has(input.dataset.draftKey))this.drafts[input.dataset.draftKey]=input.type==='checkbox'?input.checked:input.value;}
  restoreDrafts(){for(const input of this.host.querySelectorAll('[data-draft-key]'))if(Object.hasOwn(this.drafts,input.dataset.draftKey)){if(input.type==='checkbox')input.checked=this.drafts[input.dataset.draftKey];else input.value=this.drafts[input.dataset.draftKey];}}
  async load({preserve=true}={}){const e=(this.sequence||0)+1;this.sequence=e;try{const data=await this.api(this.url);if(!this.current()||this.sequence!==e)return;if(preserve)this.saveDrafts();this.data=data;this.render();for(const r of data.evidence_refs)this.addEvidence(r);}
    catch(error){if(this.current()){this.host.replaceChildren(this.node('p',error.message));const retry=this.node('button','Tải lại hồ sơ');retry.className='quiet';retry.onclick=()=>this.load();this.host.append(retry);}}}
  persist(){try{if(this.pending){const saved=structuredClone(this.pending);delete saved.payload.content_base64;sessionStorage.setItem(this.storageKey,JSON.stringify(saved));}else sessionStorage.removeItem(this.storageKey);}catch{/* retry in this tab remains available */}}
  async checksum(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');}
  async send(action,payload){if(this.busy||!this.current())return;if(!this.pending)this.pending={action,payload,request_id:crypto.randomUUID()};this.busy=true;this.status.textContent='Đang lưu trên server…';this.freeze(true);
    try{if(this.pending.action==='upload_document'){if(!this.pending.payload.content_base64){this.status.textContent='Chọn lại đúng tệp đã gửi để tiếp tục yêu cầu cũ. Nội dung tệp không được lưu trong trình duyệt.';return;}this.pending.file_sha256=await this.checksum(Uint8Array.from(atob(this.pending.payload.content_base64),c=>c.charCodeAt(0)));}this.persist();const {action,payload,request_id}=this.pending;const result=await this.api(this.url,{action,payload,request_id});if(!this.current())return;const sent=this.pending;this.saveDrafts();const root='task:'+sent.payload.task_id+':';const prefixes=sent.action==='submit_task'?[root+'result',root+'waiting',root+'doc:']:sent.action==='assign_task'?[root+'who',root+'due',root+'reason']:sent.action==='decide_task'?[root+'decision']:sent.action==='verify_document'?['verify:'+sent.payload.document_id]:['upload:'];for(const key of this.edited)if(prefixes.some(p=>key.startsWith(p))){this.edited.delete(key);delete this.drafts[key];}if(sent.action==='upload_document'||sent.action==='import_attachment')this.uploadFile=null;this.pending=null;this.persist();this.localDirty=this.edited.size>0;this.dirty(this.localDirty);await this.load({preserve:false});if(this.current()){this.status.textContent='Đã lưu hồ sơ và công việc trên server.';if(result.deduplicated_existing)this.status.textContent='T\u1ec7p \u0111\u00e3 c\u00f3 trong h\u1ed3 s\u01a1; kh\u00f4ng t\u1ea1o b\u1ea3n tr\u00f9ng.';await this.changed();}}
    catch(error){if(!this.current())return;this.status.textContent=error.message;if(error.status&&error.status<500){this.pending=null;this.persist();if(error.status===409){this.saveDrafts();await this.load();this.status.textContent='Hồ sơ đã đổi ở nơi khác. Đã tải phiên bản mới; xem lại nội dung trước khi gửi.';}}else this.status.textContent+=' Bấm Tiếp tục yêu cầu đã gửi để gửi lại đúng nội dung, không tạo thao tác mới.';}
    finally{this.busy=false;if(this.current())this.freeze(false);}}
  freeze(busy){for(const f of this.host.querySelectorAll('fieldset'))f.disabled=busy||!!this.pending;this.retry.hidden=!this.pending;this.retry.disabled=busy;this.restoreFileWrap.hidden=!(this.pending?.action==='upload_document'&&!this.pending.payload.content_base64);this.restoreFile.disabled=busy;}
  button(label,action,onClick,disabled=false){const b=this.node('button',label);b.type='button';b.dataset.action=action;b.disabled=disabled;b.onclick=onClick;return b;}
  render(){const d=this.data;this.host.replaceChildren();this.host.append(this.node('h3','Chứng từ và xử lý công việc'),this.node('p',d.next_step));this.status=this.node('p');this.status.setAttribute('role','status');this.retry=this.button('Tiếp tục yêu cầu đã gửi','retry',()=>this.send());this.retry.className='quiet';const restore=this.field('Chọn lại đúng tệp của yêu cầu đã gửi','input');this.restoreFile=restore.input;this.restoreFileWrap=restore.wrap;restore.input.type='file';restore.input.accept='.pdf,.png,.jpg,.jpeg';restore.input.id='bw-document-resume-file';restore.input.onchange=async()=>{const f=restore.input.files[0];if(!f||f.size>2*1024*1024||!this.pending)return;const request=this.pending;try{const bytes=await f.arrayBuffer();if(!this.current()||request!==this.pending)return;if(await this.checksum(bytes)!==request.file_sha256){this.status.textContent='Tệp khác với yêu cầu cũ. Chọn đúng tệp đã gửi; chưa gửi thay đổi lên server.';return;}request.payload.content_base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);});if(this.current()&&request===this.pending){this.status.textContent='Đúng tệp đã gửi. Bấm Tiếp tục yêu cầu đã gửi.';this.freeze(this.busy);}}catch{if(this.current())this.status.textContent='Không đọc được tệp. Chọn lại tệp.';}};this.host.append(this.status,restore.wrap,this.retry);
    if(!d.permissions.can_verify)this.host.append(this.node('p','Bạn có thể bổ sung chứng từ và gửi kết quả. Xác minh, hoàn tất hoặc mở lại cần người có quyền xác minh.'));
    if(d.checklist){const section=this.node('details');section.append(this.node('summary','Danh mục chứng từ cần đối chiếu'));for(const item of d.checklist.items)section.append(this.node('p',item.title_vi+' · '+({unknown:'Chưa có nguồn',missing:'Đã xác nhận thiếu',pending_verification:'Chờ xác minh',present:'Đã xác minh',not_applicable:'Không áp dụng'}[item.item_status]||item.item_status)));this.host.append(section);}
    this.documents();if(d.permissions.can_upload)this.upload();this.host.append(this.node('h3','Công việc của vụ này'));
    for(const task of d.tasks)this.task(task);if(!d.tasks.length)this.host.append(this.node('p','Chưa có công việc. Giao việc ở bên dưới để xác định người phụ trách và hạn xử lý.'));
    this.host.append(this.node('p',d.separation_note));this.restoreDrafts();this.syncUpload?.();this.freeze(this.busy);
  }
  documents(){const list=this.node('div');list.id='bw-documents';this.host.append(list);
    const names={pending_verification:'Đã nhận, chờ xác minh',present:'Đã xác minh',rejected:'Bị từ chối'};
    for(const doc of this.data.documents){const card=this.node('article');card.className='bw-document';card.dataset.document=doc.document_id;const current=doc.versions.find(v=>v.version===doc.current_version);card.append(this.node('h4',(this.data.document_types.find(t=>t.key===doc.document_type)?.label||doc.document_type)+' · '+current.filename),this.node('p','Phiên bản '+doc.current_version+' · '+names[doc.verification_status]+' · Nhận lúc '+this.date(current.received_at)));
      if(doc.late_arrival_after_as_of)card.append(this.node('p','Tài liệu bổ sung sau mốc phân tích; không sửa dữ liệu hay điểm đã lưu.'));
      const versions=this.node('details');versions.append(this.node('summary','Các phiên bản và kết quả xác minh'));
      for(const version of doc.versions){const line=this.node('div');line.append(this.node('p','v'+version.version+' · '+version.filename+' · '+names[version.verification_status]));if(version.verification_note)line.append(this.node('p','Đối chiếu: '+version.verification_note));const view=this.button('Tải tài liệu v'+version.version,'download',async()=>{try{const file=await this.api(this.url+'/documents/'+doc.document_id+'/versions/'+version.version);if(this.current())this.download(Uint8Array.from(atob(file.content),c=>c.charCodeAt(0)),file.name,file.mime);}catch(error){if(this.current())this.status.textContent=error.message;}});view.className='quiet';line.append(view);versions.append(line);}card.append(versions);
      if(this.data.permissions.can_verify){const form=this.node('fieldset'),note=this.field('Căn cứ và kết quả đối chiếu chứng từ','textarea','verify:'+doc.document_id);const actions=this.node('div');actions.className='actions';actions.append(this.button('Xác minh đạt','verify',()=>this.send('verify_document',{document_id:doc.document_id,version:doc.current_version,decision:'present',note:note.input.value})),this.button('Từ chối chứng từ','reject',()=>this.send('verify_document',{document_id:doc.document_id,version:doc.current_version,decision:'rejected',note:note.input.value})));form.append(note.wrap,actions,this.node('p','Quyết định áp dụng đúng phiên bản v'+doc.current_version+' đang hiển thị.'));card.append(form);}list.append(card);
    }
    if(!this.data.documents.length)list.append(this.node('p','Chưa có chứng từ trong hồ sơ xác minh. Bản ghi nguồn và tệp đính kèm cũ chưa tự được tính là chứng từ đã xác minh.'));
  }
  upload(){const form=this.node('fieldset');form.className='bw-upload-form';form.append(this.node('legend','Bổ sung chứng từ'));const type=this.field('Loại chứng từ','select','upload:type'),target=this.field('Tệp mới hay phiên bản bổ sung?','select','upload:target'),source=this.field('Nguồn tệp','select','upload:source'),note=this.field('Ghi chú chứng từ','textarea','upload:note'),file=this.field('Chọn PDF hoặc ảnh (tối đa 2 MB)','input');file.input.type='file';file.input.accept='.pdf,.png,.jpg,.jpeg';file.input.id='bw-upload';file.input.onchange=()=>{this.uploadFile=file.input.files[0]||null;this.edited.add('upload:file');this.dirty(true);};type.input.id='bw-document-type';target.input.id='bw-document-target';
    const chosen=this.node('p',this.uploadFile?'Tệp đang chọn: '+this.uploadFile.name:'');file.wrap.append(chosen);file.input.addEventListener('change',()=>{chosen.textContent=this.uploadFile?'Tệp đang chọn: '+this.uploadFile.name:'';});
    this.options(type.input,this.data.document_types.map(t=>[t.key,t.label]));this.options(target.input,[['','Tài liệu mới'],...this.data.documents.map(d=>[d.document_id,d.versions.at(-1).filename+' — thêm phiên bản'])]);this.options(source.input,[['','Tệp trên máy'],...this.legacyAttachments.map(a=>[a.id,a.name+' — tệp đã bổ sung trước đây'])]);
    const changeTarget=()=>{const doc=this.data.documents.find(d=>d.document_id===target.input.value);if(doc)type.input.value=doc.document_type;type.input.disabled=!!doc;};target.input.onchange=changeTarget;this.syncUpload=changeTarget;
    const save=this.button('Lưu chứng từ','upload',async()=>{let content;if(source.input.value){if(target.input.value){this.status.textContent='Tệp cũ được đưa vào hồ sơ như tài liệu mới. Chọn Tài liệu mới trước khi tiếp tục.';return;}this.send('import_attachment',{attachment_id:source.input.value,document_type:type.input.value,note:note.input.value});return;}
      const f=file.input.files[0]||this.uploadFile;if(!f||!f.size||f.size>2*1024*1024){this.status.textContent='Chọn PDF/PNG/JPEG có dữ liệu và tối đa 2 MB.';return;}try{content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);});}catch{this.status.textContent='Không đọc được tệp. Chọn lại tệp để tiếp tục.';return;}
      if(this.current())this.send('upload_document',{document_type:type.input.value,filename:f.name,content_base64:content,note:note.input.value,...(target.input.value?{document_id:target.input.value}:{})});});save.id='bw-document-save';form.append(type.wrap,target.wrap,source.wrap,file.wrap,note.wrap,save,this.node('p','Tài liệu mới luôn chờ xác minh. Tệp bổ sung trước đây chỉ được đưa vào hồ sơ khi bạn chọn rõ loại chứng từ.'));this.host.append(form);
  }
  task(t){const closed=['completed','cancelled'].includes(t.status),card=this.node('article');card.className='bw-task';card.dataset.task=t.task_id;card.dataset.status=t.status;card.dataset.revision=t.revision;const labels={open:'Mở mới',in_progress:'Đang xử lý',waiting_external:'Chờ bổ sung',completed:'Đã hoàn tất',cancelled:'Đã hủy'};card.append(this.node('h4',t.title),this.node('p',(labels[t.status]||t.status)+' · '+t.assignee.display_label+' · Hạn: '+this.date(t.due_at)),this.node('p',t.what_to_do));
    if(t.submission)card.append(this.node('p','Kết quả đã gửi: '+t.submission.result_summary));if(t.verification)card.append(this.node('p','Quyết định gần nhất: '+t.verification.confirmation_note));
    const prefix='task:'+t.task_id+':';
    if(t.actions.can_submit){const form=this.node('fieldset'),result=this.field('Kết quả thực hiện','textarea',prefix+'result'),waiting=this.field('Còn chờ bổ sung từ bên ngoài','input',prefix+'waiting');waiting.input.type='checkbox';waiting.wrap.className='check';result.input.value=t.submission?.result_summary||'';const docs=this.node('div');docs.append(this.node('p','Chứng từ dùng cho kết quả này:'));const selected=[];for(const doc of this.data.documents){const check=this.field(doc.versions.at(-1).filename+' · v'+doc.current_version,'input',prefix+'doc:'+doc.document_id);check.input.type='checkbox';check.input.checked=!!t.submission?.submitted_document_ids.includes(doc.document_id);check.wrap.className='check';check.input.value=doc.document_id;selected.push(check.input);docs.append(check.wrap);}form.append(result.wrap,docs,waiting.wrap,this.button('Gửi kết quả thực hiện','submit',()=>this.send('submit_task',{task_id:t.task_id,expected_revision:t.revision,result_summary:result.input.value,document_ids:selected.filter(d=>d.checked).map(d=>d.value),waiting_external:waiting.input.checked})));card.append(form);}
    if(t.actions.can_assign){const details=this.node('details');details.append(this.node('summary','Đổi bộ phận hoặc hạn xử lý'));const form=this.node('fieldset'),who=this.field('Bộ phận phụ trách','select',prefix+'who'),due=this.field('Hạn xử lý (giờ Việt Nam)','input',prefix+'due'),reason=this.field('Lý do thay đổi','textarea',prefix+'reason');due.input.type='datetime-local';due.input.step='1';due.input.value=this.local(t.due_at);this.options(who.input,this.data.assignees.map(a=>[a.key,a.label]),t.assignee.assignee_key);form.append(who.wrap,due.wrap,reason.wrap,this.button('Lưu phân công và hạn','assign',()=>this.send('assign_task',{task_id:t.task_id,expected_revision:t.revision,assignee_key:who.input.value,due_at:due.input.value+(due.input.value.length===16?':00':'')+'+07:00',reason:reason.input.value})));details.append(form);card.append(details);}
    if(t.actions.can_verify){const form=this.node('fieldset'),note=this.field(closed?'Lý do mở lại công việc':'Căn cứ quyết định công việc','textarea',prefix+'decision');form.append(note.wrap);if(closed)form.append(this.button('Mở lại công việc','reopen',()=>this.send('decide_task',{task_id:t.task_id,expected_revision:t.revision,decision:'reopen',note:note.input.value})));else form.append(this.button('Xác nhận hoàn tất','complete',()=>this.send('decide_task',{task_id:t.task_id,expected_revision:t.revision,decision:'confirm_complete',note:note.input.value}),!t.actions.can_complete),this.button('Yêu cầu làm lại','rework',()=>this.send('decide_task',{task_id:t.task_id,expected_revision:t.revision,decision:'request_rework',note:note.input.value})));card.append(form);}
    if(!closed&&t.actions.completion_blockers.length){const missing=this.node('ul');for(const reason of t.actions.completion_blockers)missing.append(this.node('li',reason));card.append(this.node('p','Còn thiếu để hoàn tất:'),missing);}
    const history=this.node('details');history.append(this.node('summary','Lịch sử công việc'));for(const h of t.history)history.append(this.node('p',this.date(h.at)+' · '+(labels[h.to_status]||h.to_status)+' · '+h.reason));card.append(history);this.host.append(card);
  }
};
